import re, requests, concurrent.futures, time, json, os, sys
ids=[]
for line in open('sei_repo/model/target.names'):
    m=re.search(r'ID:(\\d+)',line)
    if m:
        ids.append(int(m.group(1)))
out_path='/workspace/sei_cistrome_mapping.tsv'
# skip if already exists partially? start fresh
# fetch all with sessions
from requests.adapters import HTTPAdapter
from urllib3.util.retry import Retry
sess=requests.Session()
retry=Retry(total=3, backoff_factor=0.5, status_forcelist=[500,502,503,504])
adapter=HTTPAdapter(max_retries=retry, pool_connections=64, pool_maxsize=64)
sess.mount('https://',adapter)
sess.mount('http://',adapter)
def fetch(i):
    try:
        r=sess.get(f'https://dc2.cistrome.org/api/inspector?id={i}', timeout=30)
        if r.status_code"'!=200:
            return (i, '"'HTTP'+str(r.status_code), 'ERR')
        d=r.json()
        ts=d.get('treats') or []
        if not ts:
            return (i, '', 'no_treats')
        uids='|'.join([str(x.get('unique_id')) for x in ts if x.get('unique_id')])
        return (i, uids, d.get('status',''))
    except Exception as e:
        return (i, 'ERR:'+type(e).__name__, 'ERR')
t=time.time()
with open(out_path,'w') as f:
    f.write('cistrome_id\\tunique_ids\\tstatus\\n')
    with concurrent.futures.ThreadPoolExecutor(max_workers=24) as ex:
        for n,(i,uids,st) in enumerate(ex.map(fetch,ids),1):
            f.write(f'{i}\\t{uids}\\t{st}\\n')
            if n%2000==0:
                print(f'{n}/{len(ids)} elapsed {time.time()-t:.1f}s', flush=True)
print('done', len(ids), 'elapsed', time.time()-t)
